-----------------------------------------------------------------
---- AJUSTES DE MIARCH (los cambia el panel de Ajustes) ----
-----------------------------------------------------------------
local ESCALA = "auto"    -- escala de pantalla: auto | 1 | 1.25 | 1.5 | 2
local KB = "latam"   -- distribución del teclado: latam | us | es
local NATURAL = "on"     -- desplazamiento natural del touchpad: on | off
local TAP = "on"      -- tocar para hacer clic: on | off
local SENS = "0"       -- sensibilidad del puntero: -0.5 … 0.5
local CURSOR = "24"      -- tamaño del cursor: 24 | 32 | 40 | 48
local MOVIMIENTO = "on"      -- animaciones: on | off (off = reducir movimiento)

------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/configuring/core/monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = (ESCALA == "auto") and "auto" or tonumber(ESCALA),
})


