-- Miarch: nivel de desenfoque (se cambia desde el panel de Ajustes)
local BLUR = "medio"
local blurs = {
    ninguno = { enabled = false, size = 3,  passes = 1, vibrancy = 0.17 },
    suave   = { enabled = true,  size = 4,  passes = 2, vibrancy = 0.17 },
    medio   = { enabled = true,  size = 7,  passes = 3, vibrancy = 0.20 },
    fuerte  = { enabled = true,  size = 10, passes = 4, vibrancy = 0.20 },
    extremo = { enabled = true,  size = 14, passes = 5, vibrancy = 0.25 },
}
local b = blurs[BLUR] or blurs.fuerte

-- Refer to https://wiki.hypr.land/configuring/core/config-options/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 20,

        border_size = 2,

        col = {
            -- Miarch: bordes mate (sin neón), mismos tonos que la Waybar
            active_border   = { colors = {"rgba(b9b2a6ff)", "rgba(8f8a84ff)"}, angle = 90 },
            inactive_border = "rgba(26262bcc)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = true,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    decoration = {
        rounding       = 10,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = true,
            range        = 14,
            render_power = 3,
            color        = 0x66000000,   -- sombra suave y oscura, sin color
        },

        -- Miarch: blur fuerte, parecido al de la pantalla de bloqueo
        blur = {
            enabled    = b.enabled,
            size       = b.size,
            passes     = b.passes,
            noise      = 0.015,
            contrast   = 0.9,
            brightness = 0.85,
            vibrancy   = b.vibrancy,
            popups     = true,
        },
    },

    animations = {
        enabled = (MOVIMIENTO == "on"),
    },
})

-- ── Animaciones · cambia el preset con:  miarch-anim <nombre> ──────────────
--   slide (deslizamiento cinematográfico) · zoom · suave (solo fundido) · elastico · original
local ANIM = "elastico"

hl.curve("expo",         { type = "bezier", points = { {0.16, 1},    {0.3, 1}     } })
hl.curve("cine",         { type = "bezier", points = { {0.22, 1},    {0.36, 1}    } })
hl.curve("linear",       { type = "bezier", points = { {0, 0},       {1, 1}       } })
hl.curve("quick",        { type = "bezier", points = { {0.15, 0},    {0.1, 1}     } })
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5},   {0.75, 1}    } })
hl.curve("easeOutQuint", { type = "bezier", points = { {0.23, 1},    {0.32, 1}    } })
hl.curve("easy",         { type = "spring", mass = 1, stiffness = 238.1191, damping = 24.21279333 })

-- curva que empieza con "~" = resorte
local function anim(leaf, speed, curva, style)
    local t = { leaf = leaf, enabled = true, speed = speed }
    if curva:sub(1, 1) == "~" then t.spring = curva:sub(2) else t.bezier = curva end
    if style then t.style = style end
    hl.animation(t)
end

local presets = {
    slide = function()
        anim("global", 10, "default")
        anim("border", 8, "cine")
        anim("windows", 6, "expo", "slide")
        anim("windowsIn", 6, "expo", "slide")
        anim("windowsOut", 5, "cine", "slide")
        anim("fade", 5, "cine"); anim("fadeIn", 5, "cine"); anim("fadeOut", 4, "cine")
        anim("layers", 6, "expo"); anim("layersIn", 6, "expo", "slide"); anim("layersOut", 5, "cine", "slide")
        anim("fadeLayersIn", 5, "cine"); anim("fadeLayersOut", 4, "cine")
        anim("workspaces", 7, "expo", "slide"); anim("workspacesIn", 7, "expo", "slide"); anim("workspacesOut", 7, "expo", "slide")
    end,
    zoom = function()
        anim("global", 10, "default")
        anim("border", 8, "cine")
        anim("windows", 6, "expo")
        anim("windowsIn", 6, "expo", "popin 55%")
        anim("windowsOut", 4, "cine", "popin 55%")
        anim("fade", 5, "cine"); anim("fadeIn", 5, "cine"); anim("fadeOut", 4, "cine")
        anim("layers", 6, "expo"); anim("layersIn", 6, "expo", "popin 70%"); anim("layersOut", 4, "cine", "fade")
        anim("workspaces", 7, "expo", "slidefade 25%"); anim("workspacesIn", 7, "expo", "slidefade 25%"); anim("workspacesOut", 7, "expo", "slidefade 25%")
    end,
    suave = function()
        anim("global", 10, "default")
        anim("border", 6, "quick")
        anim("windows", 4, "quick")
        anim("windowsIn", 4, "quick", "popin 94%")
        anim("windowsOut", 3, "quick", "popin 94%")
        anim("fade", 4, "quick"); anim("fadeIn", 4, "quick"); anim("fadeOut", 3, "quick")
        anim("layers", 4, "quick", "fade")
        anim("workspaces", 4, "quick", "fade")
    end,
    elastico = function()
        anim("global", 10, "default")
        anim("border", 8, "cine")
        anim("windows", 4.8, "~easy")
        anim("windowsIn", 4.1, "~easy", "popin 70%")
        anim("windowsOut", 3, "cine", "popin 70%")
        anim("fade", 4, "cine")
        anim("layers", 5, "~easy", "slide")
        anim("workspaces", 6, "expo", "slide")
    end,
    original = function()
        anim("global", 10, "default")
        anim("border", 5.39, "easeOutQuint")
        anim("windows", 4.79, "~easy")
        anim("windowsIn", 4.1, "~easy", "popin 87%")
        anim("windowsOut", 1.49, "linear", "popin 87%")
        anim("fadeIn", 1.73, "almostLinear"); anim("fadeOut", 1.46, "almostLinear"); anim("fade", 3.03, "quick")
        anim("layers", 3.81, "easeOutQuint"); anim("layersIn", 4, "easeOutQuint", "fade"); anim("layersOut", 1.5, "linear", "fade")
        anim("workspaces", 1.94, "almostLinear", "fade")
    end,
}
;(presets[ANIM] or presets.slide)()
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

