-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Miarch: Waybar entra deslizando desde arriba, con blur detrás de las islas
hl.layer_rule({
    name  = "waybar-fx",
    match = { namespace = "^waybar$" },
    blur        = true,
    ignore_alpha = 0.2,
    animation   = "slide top",
})

-- Miarch: Dolphin ligeramente translúcido, para que tome el desenfoque como la terminal
hl.window_rule({
    name  = "dolphin-vidrio",
    match = { class = "org.kde.dolphin" },
    opacity = "0.93 0.88",
})

-- Miarch: el velo del lanzador de apps desenfoca todo lo que hay detrás
hl.layer_rule({
    name  = "miarch-lanzador-blur",
    match = { namespace = "^miarch-(lanzador|ajustes|conexiones)$" },
    blur         = true,
    ignore_alpha = 0.05,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
